From 779b0974dae2a8315785630895ca135a743e452a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:58:53 +0100
Subject: [PATCH] applets/pager: allow showing activity icons in the activity
 pager

Activities have an icon, but the activity pager could only label them
with a number or a name. Add an "Activity icon" display option to the
activity pager, which draws each activity's icon in its rectangle.

BUG: 364535
---
 applets/pager/main.xml              |  1 +
 applets/pager/pagermodel.cpp        |  4 ++++
 applets/pager/qml/configGeneral.qml | 13 ++++++++++++-
 applets/pager/qml/main.qml          | 24 ++++++++++++++++++++++++
 4 files changed, 41 insertions(+), 1 deletion(-)

diff --git a/applets/pager/main.xml b/applets/pager/main.xml
index d47b935b1e..0fb378f99a 100644
--- a/applets/pager/main.xml
+++ b/applets/pager/main.xml
@@ -12,6 +12,7 @@
             <choice name="Number"/>
             <choice name="Name"/>
             <choice name="None"/>
+            <choice name="Icon"/>
         </choices>
         <default>2</default>
     </entry>
diff --git a/applets/pager/pagermodel.cpp b/applets/pager/pagermodel.cpp
index 6e476f3d15..4d9db31feb 100644
--- a/applets/pager/pagermodel.cpp
+++ b/applets/pager/pagermodel.cpp
@@ -222,6 +222,10 @@ QVariant PagerModel::data(const QModelIndex &index, int role) const
             QString activityId = d->activityInfo->runningActivities().at(index.row());
             return d->activityInfo->activityName(activityId);
         }
+    } else if (role == Qt::DecorationRole) {
+        if (d->pagerType == Activities) {
+            return d->activityInfo->activityIcon(d->activityInfo->runningActivities().at(index.row()));
+        }
     } else if (role == TasksModel) {
         return QVariant::fromValue(d->windowModels.at(index.row()));
     }
diff --git a/applets/pager/qml/configGeneral.qml b/applets/pager/qml/configGeneral.qml
index 23074d9ab6..ca39d96ade 100644
--- a/applets/pager/qml/configGeneral.qml
+++ b/applets/pager/qml/configGeneral.qml
@@ -82,7 +82,9 @@ KCM.SimpleKCM {
         QQC2.RadioButton {
             id: noTextRadio

-            Kirigami.FormData.label: i18nc("@title:group prefix for radiobutton group", "Text display:")
+            Kirigami.FormData.label: root.isActivityPager
+                ? i18nc("@title:group prefix for radiobutton group", "Display:")
+                : i18nc("@title:group prefix for radiobutton group", "Text display:")

             QQC2.ButtonGroup.group: displayedTextGroup
             text: i18nc("@option:radio text display", "No text")
@@ -106,6 +108,15 @@ KCM.SimpleKCM {
             onToggled: if (checked) root.cfg_displayedText = 1;
         }

+        QQC2.RadioButton {
+            id: activityIconRadio
+            QQC2.ButtonGroup.group: displayedTextGroup
+            text: i18nc("@option:radio text display", "Activity icon")
+            visible: root.isActivityPager
+            checked: root.cfg_displayedText === 3
+            onToggled: if (checked) root.cfg_displayedText = 3;
+        }
+

         Item {
             Kirigami.FormData.isSection: true
diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..62caad85c9 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -201,6 +201,24 @@ PlasmoidItem {
         }
     }

+    Component {
+        id: activityIconComponent
+
+        Kirigami.Icon {
+            required property KSvg.FrameSvgItem desktopFrame
+
+            anchors {
+                fill: parent
+                topMargin: desktopFrame.margins.top
+                leftMargin: desktopFrame.margins.left
+                rightMargin: desktopFrame.margins.right
+                bottomMargin: desktopFrame.margins.bottom
+            }
+
+            z: 9999 // The icon goes above everything
+        }
+    }
+
     Component {
         id: windowIconComponent

@@ -313,6 +331,7 @@ PlasmoidItem {

             component DesktopDelegate: PlasmaCore.ToolTipArea {
                 required property string display
+                required property var decoration
                 required property int index
                 required property var model

@@ -588,6 +607,11 @@ PlasmoidItem {
                             display: Qt.binding(() => desktop.display),
                             desktopFrame,
                         });
+                    } else if (Plasmoid.configuration.displayedText === 3 && root.isActivityPager) {
+                        activityIconComponent.createObject(desktop, {
+                            source: Qt.binding(() => desktop.decoration),
+                            desktopFrame,
+                        });
                     }
                 }

-- 
2.53.0
